<head>
<style>
  body {
    margin: 0;
    padding: var(--cc-space-l);
    box-sizing: border-box;
    font-family: var(--cc-font-family);
    color: var(--cc-color-text);
    background: var(--cc-color-background);
  }

  .banner {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: var(--cc-space-xl);
    width: 100%;
    box-sizing: border-box;
    padding: var(--cc-space-xl);
    border-radius: var(--cc-radius);
    background: linear-gradient(120deg, #07141f 0%, #0b3d42 35%, #0b5e6b 60%, #1a73e8 100%);
    box-shadow: 0 2px 12px rgba(0,0,0,0.25);
  }

  .logos {
    display: flex;
    align-items: center;
    gap: var(--cc-space-m);
    flex-shrink: 0;
  }

  .logo-item {
    display: flex;
    align-items: center;
    gap: var(--cc-space-s);
  }

  .logo-item span {
    font-size: 0.875rem;
    font-weight: 600;
    color: #ffffff;
    white-space: nowrap;
  }

  .plus {
    font-size: 1.5rem;
    font-weight: 600;
    color: rgba(255,255,255,0.6);
  }

  .divider {
    width: 1px;
    align-self: stretch;
    background: rgba(255,255,255,0.25);
  }

  .text-block {
    display: flex;
    flex-direction: column;
    gap: var(--cc-space-xs);
    max-width: 32rem;
  }

  .title {
    font-size: 1.5rem;
    font-weight: 600;
    color: #ffffff;
    line-height: 1.2;
  }

  .subtitle {
    font-size: 0.875rem;
    font-weight: 400;
    color: rgba(255,255,255,0.85);
    line-height: 1.4;
  }

  .elastic-chip {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 40px;
    height: 40px;
    border-radius: var(--cc-radius-s);
    box-shadow: 0 1px 4px rgba(0,0,0,0.2);
    box-sizing: border-box;
  }

  @media (max-width: 700px) {
    .banner {
      flex-wrap: wrap;
      justify-content: center;
      text-align: center;
    }
    .divider { display: none; }
    .text-block { align-items: center; }
  }
</style>
</head>
<body>

